Y=2a59a0ae-9877-45dd-b26b-66f8ed6dff74; S=11111111-0000-0000-0000-000000000007; M=11111111-0000-0000-0000-000000000001; J=11111111-0000-0000-0000-000000000002; A=11111111-0000-0000-0000-000000000005; N=11111111-0000-0000-0000-000000000006; T=11111111-0000-0000-0000-000000000008
fail=0
chk(){ desc="$1"; exp="$2"; shift 2; got=$(./as.sh "$@" | grep -v '^anon$\|^authenticated$\|^service_role$' | tr '\n' ';'); if [[ "$got" == *"$exp"* ]]; then echo "PASS $desc"; else echo "FAIL $desc => $got"; fail=1; fi; }
chk "anon reads no users" "0;" anon "" "select count(*) from users"
chk "stranger sees only self" "1;" authenticated $S "select count(*) from users"
chk "stranger no BV" "0|0;" authenticated $S "select * from get_partner_monthly_bv('$M','2000-01-01')"
chk "stranger no checkins rpc" "0;" authenticated $S "select count(*) from get_partner_daily_checkins('$M','2000-01-01')"
chk "stranger cannot steal" "0;" authenticated $S "with x as (update users set referrer_id='$S' where id='$A' returning 1) select count(*) from x"
chk "Yu tree" "Amy|1|0;小美|1|2;Lisa|2|0;阿傑|2|1;春嬌|3|0;" authenticated $Y "select name, depth, referred_count from get_partner_tree() order by depth, name"
chk "Yu direct BV" "100|0;" authenticated $Y "select * from get_partner_monthly_bv('$M','2000-01-01')"
chk "Yu level2 no BV" "0|0;" authenticated $Y "select * from get_partner_monthly_bv('$J','2000-01-01')"
chk "Yu level2 checkins rpc" "1;" authenticated $Y "select count(*) from get_partner_daily_checkins('$J',date_trunc('month',current_date)::date)"
chk "teammate tx table hidden" "0;" authenticated $Y "select count(*) from transactions where user_id='$T'"
chk "own tx" "1;" authenticated $Y "select count(*) from transactions"
chk "Yu downline checkins table" "1;" authenticated $Y "select count(*) from daily_checkins where user_id='$J'"
chk "Yu stranger checkins none" "0;" authenticated $Y "select count(*) from daily_checkins where user_id='$S'"
chk "Yu teammate checkins" "1;" authenticated $Y "select count(*) from daily_checkins where user_id='$T'"
chk "Jay no upline BV" "0|0;" authenticated $J "select * from get_partner_monthly_bv('$M','2000-01-01')"
chk "pending" "志明;" authenticated $Y "select name from get_pending_partners()"
chk "wrong person confirm" "f;" authenticated $M "select confirm_partner('$N')"
chk "confirm" "t;" authenticated $Y "select confirm_partner('$N')"
chk "names filter" "小美;阿傑;隊友T;" authenticated $Y "select name from get_people_names(array['$M','$S','$T','$J']::uuid[]) order by 1"
chk "referrer name" "小美;" authenticated $J "select name from get_people_names(array['$M','$Y']::uuid[])"
chk "admin yes" "t;" authenticated $Y "select is_admin()"
chk "admin no" "f;" authenticated $M "select is_admin()"
chk "non-admin announce blocked" "ERROR" authenticated $M "insert into announcements(author_id,title) values ('$M','x')"
chk "admin announce" "x;" authenticated $Y "insert into announcements(author_id,title) values ('$Y','x') returning title"
chk "non-admin public link blocked" "0;" authenticated $M "with x as (update resource_links set title='h' where scope='public' returning 1) select count(*) from x"
chk "teams hidden" "0;" authenticated $M "select count(*) from teams"
chk "own team visible" "隊A;" authenticated $A "select name from teams"
chk "create team returning" "新隊;" authenticated $S "insert into teams(name,invite_code,creator_id) values ('新隊','QQQ','$S') returning name"
chk "own update" "小美2;" authenticated $M "update users set name='小美2' where id='$M' returning name"
chk "self admin blocked" "denied" authenticated $M "insert into admins(user_id) values ('$M')"
chk "last_seen blocked" "denied" authenticated $M "select * from admin_last_seen()"
chk "service last_seen" "2;" service_role "" "select count(*) from admin_last_seen()"
